import React, { useState } from 'react';
import { 
  Bus, 
  User, 
  ShieldCheck, 
  Mail, 
  Lock, 
  Phone, 
  Eye, 
  EyeOff, 
  ArrowRight,
  CheckCircle2
} from 'lucide-react';

export default function AuthPage({ onLoginSuccess }) {
  // Role state: 'user' or 'admin'
  const [role, setRole] = useState('user');
  
  // Auth Mode: Opens directly on Sign In (false)
  const [isSignUp, setIsSignUp] = useState(false);

  // Form Fields
  const [formData, setFormData] = useState({
    name: '',
    emailOrPhone: '', // Dual field for email or Bangladesh phone number
    phone: '',
    password: '',
    confirmPassword: '',
  });

  const [showPassword, setShowPassword] = useState(false);
  const [error, setError] = useState('');

  const handleInputChange = (e) => {
    setFormData({ ...formData, [e.target.name]: e.target.value });
  };

  const handleSubmit = (e) => {
    e.preventDefault();
    setError('');

    if (isSignUp) {
      // Registration Validations
      if (!formData.name || !formData.emailOrPhone || !formData.phone || !formData.password || !formData.confirmPassword) {
        setError('Please fill in all registration fields.');
        return;
      }
      if (formData.password !== formData.confirmPassword) {
        setError('Passwords do not match!');
        return;
      }
      if (formData.password.length < 6) {
        setError('Password must be at least 6 characters long.');
        return;
      }
    } else {
      // Sign In Validations (Only Email/Phone + Password)
      if (!formData.emailOrPhone || !formData.password) {
        setError('Please enter your Mobile Number or Email and Password.');
        return;
      }
    }

    const payload = {
      ...formData,
      role: role,
    };

    console.log(`Submitting ${isSignUp ? 'Sign Up' : 'Sign In'} for ${role}:`, payload);

    if (onLoginSuccess) {
      onLoginSuccess({ name: formData.name || 'Passenger', emailOrPhone: formData.emailOrPhone, role: role });
    }
  };

  return (
    <div style={styles.pageContainer}>
      <div style={styles.authWrapper}>

        {/* LEFT COLUMN: Bangladesh Branding Showcase */}
        <div style={styles.leftSection}>
          <div style={styles.brandGroup}>
            <div style={styles.logoBadge}>
              <Bus size={30} color="#000000" />
            </div>
            <div>
              <h1 style={styles.leftTitle}>ONLINE BUS</h1>
              <span style={styles.bdBadge}>BANGLADESH</span>
            </div>
          </div>

          <div style={styles.leftHeroContent}>
            <h2 style={styles.heroHeading}>
              Travel across Bangladesh smoothly.
            </h2>
            <p style={styles.heroSubtext}>
              Book tickets for AC & Non-AC routes between Dhaka, Chattogram, Sylhet, Cox's Bazar, and all major divisions.
            </p>

            <div style={styles.featureList}>
              <div style={styles.featureItem}>
                <CheckCircle2 size={18} color="#ffffff" />
                <span>Real-time seat selection layout</span>
              </div>
              <div style={styles.featureItem}>
                <CheckCircle2 size={18} color="#ffffff" />
                <span>bKash, Nagad, Rocket & Card payments</span>
              </div>
              <div style={styles.featureItem}>
                <CheckCircle2 size={18} color="#ffffff" />
                <span>Instant SMS & downloadable E-Ticket</span>
              </div>
            </div>
          </div>

          <div style={styles.leftFooter}>
            © {new Date().getFullYear()} Online Bus Bangladesh. All rights reserved.
          </div>
        </div>

        {/* RIGHT COLUMN: Sign In / Sign Up Form */}
        <div style={styles.rightSection}>
          
          {/* Passenger vs Admin Toggle */}
          <div style={styles.roleToggle}>
            <button
              type="button"
              onClick={() => { setRole('user'); setError(''); }}
              style={{
                ...styles.roleBtn,
                ...(role === 'user' ? styles.activeRole : {}),
              }}
            >
              <User size={16} /> Passenger
            </button>
            <button
              type="button"
              onClick={() => { setRole('admin'); setError(''); }}
              style={{
                ...styles.roleBtn,
                ...(role === 'admin' ? styles.activeRole : {}),
              }}
            >
              <ShieldCheck size={16} /> Admin Portal
            </button>
          </div>

          {/* Form Header */}
          <div style={styles.formHeader}>
            <h2 style={styles.formTitle}>
              {isSignUp ? `Create ${role === 'admin' ? 'Admin' : 'Passenger'} Account` : `Sign In to Online Bus`}
            </h2>
            <p style={styles.formSubtext}>
              {isSignUp ? 'Fill details below to register for online bus booking.' : 'Welcome back! Please enter your account credentials.'}
            </p>
          </div>

          {/* Error Banner */}
          {error && <div style={styles.errorAlert}>{error}</div>}

          {/* Form Inputs */}
          <form onSubmit={handleSubmit} style={styles.form}>
            
            {/* Name (Sign Up Only) */}
            {isSignUp && (
              <div style={styles.inputGroup}>
                <label style={styles.label}>Full Name</label>
                <div style={styles.inputWrapper}>
                  <User size={18} style={styles.inputIcon} />
                  <input
                    type="text"
                    name="name"
                    placeholder="e.g. Tanvir Hossain"
                    value={formData.name}
                    onChange={handleInputChange}
                    style={styles.input}
                  />
                </div>
              </div>
            )}

            {/* Email / Mobile Field (Sign In & Sign Up) */}
            <div style={styles.inputGroup}>
              <label style={styles.label}>
                {isSignUp ? 'Email Address' : 'Mobile Number or Email'}
              </label>
              <div style={styles.inputWrapper}>
                <Mail size={18} style={styles.inputIcon} />
                <input
                  type="text"
                  name="emailOrPhone"
                  placeholder={
                    isSignUp
                      ? 'passenger@example.com'
                      : '017XXXXXXXX or email@domain.com'
                  }
                  value={formData.emailOrPhone}
                  onChange={handleInputChange}
                  style={styles.input}
                />
              </div>
            </div>

            {/* Mobile Number (Sign Up Only) */}
            {isSignUp && (
              <div style={styles.inputGroup}>
                <label style={styles.label}>Mobile Number</label>
                <div style={styles.inputWrapper}>
                  <Phone size={18} style={styles.inputIcon} />
                  <input
                    type="tel"
                    name="phone"
                    placeholder="01712345678"
                    value={formData.phone}
                    onChange={handleInputChange}
                    style={styles.input}
                  />
                </div>
              </div>
            )}

            {/* Password */}
            <div style={styles.inputGroup}>
              <label style={styles.label}>Password</label>
              <div style={styles.inputWrapper}>
                <Lock size={18} style={styles.inputIcon} />
                <input
                  type={showPassword ? 'text' : 'password'}
                  name="password"
                  placeholder="••••••••"
                  value={formData.password}
                  onChange={handleInputChange}
                  style={styles.input}
                />
                <button
                  type="button"
                  onClick={() => setShowPassword(!showPassword)}
                  style={styles.eyeBtn}
                >
                  {showPassword ? <EyeOff size={18} /> : <Eye size={18} />}
                </button>
              </div>
            </div>

            {/* Confirm Password (Sign Up Only) */}
            {isSignUp && (
              <div style={styles.inputGroup}>
                <label style={styles.label}>Confirm Password</label>
                <div style={styles.inputWrapper}>
                  <Lock size={18} style={styles.inputIcon} />
                  <input
                    type={showPassword ? 'text' : 'password'}
                    name="confirmPassword"
                    placeholder="••••••••"
                    value={formData.confirmPassword}
                    onChange={handleInputChange}
                    style={styles.input}
                  />
                </div>
              </div>
            )}

            {/* Submit Button */}
            <button type="submit" style={styles.submitBtn}>
              <span>{isSignUp ? 'Register Account' : 'Sign In'}</span>
              <ArrowRight size={18} />
            </button>
          </form>

          {/* Toggle between Sign In & Sign Up */}
          <div style={styles.switchContainer}>
            <span>
              {isSignUp ? 'Already registered?' : "Don't have an account?"}
            </span>
            <button
              type="button"
              onClick={() => {
                setIsSignUp(!isSignUp);
                setError('');
              }}
              style={styles.switchBtn}
            >
              {isSignUp ? 'Sign In' : 'Sign Up'}
            </button>
          </div>

        </div>

      </div>
    </div>
  );
}

// Black & Off-White Styling Rules
const styles = {
  pageContainer: {
    minHeight: '100vh',
    display: 'flex',
    alignItems: 'center',
    justifyContent: 'center',
    backgroundColor: '#f4f4f5',
    padding: '24px',
    fontFamily: '-apple-system, BlinkMacSystemFont, "Segoe UI", Roboto, sans-serif',
  },
  authWrapper: {
    display: 'flex',
    width: '100%',
    maxWidth: '960px',
    minHeight: '600px',
    backgroundColor: '#ffffff',
    borderRadius: '20px',
    overflow: 'hidden',
    boxShadow: '0 20px 40px rgba(0, 0, 0, 0.08)',
    border: '1px solid #e4e4e7',
  },
  leftSection: {
    flex: '1',
    backgroundColor: '#09090b',
    color: '#fafafa',
    padding: '48px 40px',
    display: 'flex',
    flexDirection: 'column',
    justifyContent: 'space-between',
  },
  brandGroup: {
    display: 'flex',
    alignItems: 'center',
    gap: '12px',
  },
  logoBadge: {
    backgroundColor: '#fafafa',
    padding: '8px',
    borderRadius: '10px',
    display: 'flex',
  },
  leftTitle: {
    fontSize: '1.25rem',
    fontWeight: '800',
    letterSpacing: '1px',
    margin: 0,
    lineHeight: '1',
  },
  bdBadge: {
    fontSize: '0.65rem',
    fontWeight: '700',
    color: '#a1a1aa',
    letterSpacing: '2px',
  },
  leftHeroContent: {
    margin: '32px 0',
  },
  heroHeading: {
    fontSize: '1.85rem',
    fontWeight: '700',
    lineHeight: '1.25',
    margin: '0 0 16px 0',
  },
  heroSubtext: {
    color: '#a1a1aa',
    fontSize: '0.9rem',
    lineHeight: '1.5',
    margin: '0 0 24px 0',
  },
  featureList: {
    display: 'flex',
    flexDirection: 'column',
    gap: '12px',
  },
  featureItem: {
    display: 'flex',
    alignItems: 'center',
    gap: '10px',
    fontSize: '0.85rem',
    color: '#e4e4e7',
  },
  leftFooter: {
    fontSize: '0.75rem',
    color: '#71717a',
  },
  rightSection: {
    flex: '1.1',
    backgroundColor: '#ffffff',
    padding: '40px 36px',
    display: 'flex',
    flexDirection: 'column',
    justifyContent: 'center',
  },
  roleToggle: {
    display: 'flex',
    backgroundColor: '#f4f4f5',
    borderRadius: '10px',
    padding: '4px',
    marginBottom: '20px',
    border: '1px solid #e4e4e7',
  },
  roleBtn: {
    flex: 1,
    display: 'flex',
    alignItems: 'center',
    justifyContent: 'center',
    gap: '8px',
    padding: '8px 0',
    fontSize: '0.85rem',
    fontWeight: '600',
    border: 'none',
    borderRadius: '8px',
    backgroundColor: 'transparent',
    color: '#71717a',
    cursor: 'pointer',
    transition: 'all 0.2s',
  },
  activeRole: {
    backgroundColor: '#09090b',
    color: '#ffffff',
  },
  formHeader: {
    marginBottom: '16px',
  },
  formTitle: {
    fontSize: '1.35rem',
    fontWeight: '700',
    color: '#09090b',
    margin: '0 0 4px 0',
  },
  formSubtext: {
    fontSize: '0.85rem',
    color: '#71717a',
    margin: 0,
  },
  errorAlert: {
    backgroundColor: '#09090b',
    color: '#ffffff',
    padding: '10px 14px',
    borderRadius: '8px',
    fontSize: '0.85rem',
    marginBottom: '16px',
  },
  form: {
    display: 'flex',
    flexDirection: 'column',
    gap: '12px',
  },
  inputGroup: {
    display: 'flex',
    flexDirection: 'column',
    gap: '4px',
  },
  label: {
    fontSize: '0.75rem',
    fontWeight: '700',
    color: '#09090b',
    textTransform: 'uppercase',
    letterSpacing: '0.5px',
  },
  inputWrapper: {
    position: 'relative',
    display: 'flex',
    alignItems: 'center',
  },
  inputIcon: {
    position: 'absolute',
    left: '12px',
    color: '#a1a1aa',
  },
  input: {
    width: '100%',
    padding: '10px 12px 10px 38px',
    borderRadius: '8px',
    border: '1px solid #d4d4d8',
    backgroundColor: '#fafafa',
    fontSize: '0.9rem',
    outline: 'none',
    boxSizing: 'border-box',
    color: '#09090b',
  },
  eyeBtn: {
    position: 'absolute',
    right: '12px',
    background: 'none',
    border: 'none',
    color: '#a1a1aa',
    cursor: 'pointer',
  },
  submitBtn: {
    display: 'flex',
    alignItems: 'center',
    justifyContent: 'center',
    gap: '8px',
    padding: '12px',
    borderRadius: '8px',
    border: 'none',
    backgroundColor: '#09090b',
    color: '#ffffff',
    fontSize: '0.95rem',
    fontWeight: '600',
    cursor: 'pointer',
    marginTop: '8px',
  },
  switchContainer: {
    display: 'flex',
    justifyContent: 'center',
    alignItems: 'center',
    gap: '6px',
    marginTop: '20px',
    fontSize: '0.85rem',
    color: '#71717a',
  },
  switchBtn: {
    background: 'none',
    border: 'none',
    color: '#09090b',
    fontWeight: '700',
    cursor: 'pointer',
    textDecoration: 'underline',
  },
};
